declare(strict_types=1);

namespace App\Modules\Contracts\Application;

use App\Modules\Contracts\Domain\Contract;
use App\Modules\Contracts\Domain\ContractStatus;
use App\Platform\Identity\Domain\User;
use App\Platform\Notifications\Notifier;
use Psr\Log\LoggerInterface;
use Throwable;

/**
 * Notifications of the Contracts module through the platform Notifier (template "contract.status_changed", seeded in
 * uz/ru/en; in-app immediately, e-mail asynchronously; users may opt out of category "contracts").
 * Delivery problems never break the business transaction.
 */
final class ContractNotifier
{
    public const TEMPLATE = 'contract.status_changed';
    public const CATEGORY = 'contracts';
    public const CHANNELS = ['inapp', 'email'];

    public function __construct(
        private readonly Notifier $notifier,
        private readonly LoggerInterface $logger,
    ) {}

    /** Status change: informs the referenced users (and the creator) except the actor. */
    public function statusChanged(User $actor, Contract $entity, ContractStatus $to): int
    {
        return $this->send($actor, $entity, ['status' => $to->label()]);
    }

    /** @return int number of users notified */
    private function send(User $actor, Contract $entity, array $params): int
    {
        $recipients = array_values(array_unique(array_filter([$entity->ownerId(), $entity->createdBy], static fn($id) => is_string($id) && $id !== '' && $id !== $actor->id)));
        $sent = 0;
        foreach ($recipients as $userId) {
            try {
                $this->notifier->notify($userId, self::TEMPLATE, $params + [
                    'record' => $entity->displayTitle(),
                    'actor' => $actor->displayName(),
                ], self::CHANNELS, self::CATEGORY);
                $sent++;
            } catch (Throwable $e) {
                $this->logger->warning('Contract notification failed: {e}', ['e' => $e->getMessage()]);
            }
        }
        return $sent;
    }
}
